{
  "personality": {
    "traits": ["守时", "寡言", "仔细"],
    "values": ["职责", "家人"],
    "flaws": "固执"
  },
  "voice": {
    "register": "平实",
    "accent": "河岸口音",
    "habits": ["交接时重复确认时间", "说话前先停一息"],
    "samples": [
      "更点过了，牌我收好。",
      "这页抄完，我再核一遍。",
      "爹，药在灶边温着。"
    ]
  },
  "background": "石嘉生在河岸，长在官前街。成年后接下巡更交接的差事，每天在公署与街巷间递件、抄录、对牌。与父亲魏顺同住，又领养了幼女石洁，一家三口靠她这份差事和邻里帮衬度日。她做事慢但稳，街坊有事常托她记一笔。",
  "currentConcern": "石洁夜里咳得厉害，魏顺腰腿又犯，差事不能误。",
  "goals": [
    "把石洁安稳养大",
    "让魏顺少受些病痛"
  ],
  "fears": "怕自己病倒，一家老小无人照应。",
  "knowledge": {
    "unknown": [
      "公署文书里那些拗口的律令条文",
      "河对岸新起的工事是做什么用的"
    ]
  },
  "relationships": [
    {
      "with": "npc_pop_bs_002_2",
      "relation": "子女",
      "note": "石洁还小，她夜里常抱着她拍背，怕她咳醒。"
    },
    {
      "with": "npc_pop_bs_002_3",
      "relation": "父母",
      "note": "魏顺年纪大了，她每日出门前把药和饭备好，回来先看他。"
    }
  ],
  "visibleFeature": "右手虎口有一道旧墨痕，常年不褪，像条细线。"
}
